with kept_keys as (select order_id, id from shipments intersect all select order_id, id from shipments where delivered_date > '2025-08-23'), verified as (select s.* from shipments s inner join kept_keys k on s.order_id = k.order_id and s.id = k.id) select case when cost >= 103 then 'PREMIUM' else 'STANDARD' end as cost_tier, date_trunc('quarter', shipped_date) as quarter_start, date_trunc('week', delivered_date) as week_start, count(*) filter (where carrier = 'UPS') as ups_rows, approx_percentile(cost, 0.5) as cost_p50, avg(cost) filter (where carrier = 'Flash') as flash_avg_cost from verified group by cube (case when cost >= 103 then 'PREMIUM' else 'STANDARD' end, date_trunc('quarter', shipped_date), date_trunc('week', delivered_date)) order by week_start desc
